<script setup>import { onMounted, ref } from "vue"; import AdminLayout from "../../layouts/AdminLayout.vue"; import StatusBadge from "../../components/StatusBadge.vue"; import { userService } from "../../services/api"; const users = ref([]), error = ref(""), toast = ref(""); const load = async () => { try { users.value = (await userService.pending()).data; } catch (exception) { error.value = exception.message; } }; const act = async (user, type) => { if (type === "reject" && !confirm(`Refuser le compte de ${user.nom_complet} ?`)) return; try { await userService[type](user.id); toast.value = `Compte ${type === 'approve' ? 'approuvé' : 'refusé'}.`; await load(); } catch (exception) { error.value = exception.message; } }; onMounted(load);</script><template><AdminLayout><section class="p-5 md:p-10"><h1 class="text-3xl font-bold">Utilisateurs</h1><p class="mt-2 text-slate-500">Les routes actuelles exposent les comptes en attente de validation.</p><div v-if="error" class="alert alert-error mt-6">{{ error }}</div><div v-else class="mt-7 overflow-x-auto rounded-2xl bg-white shadow-sm"><table class="table"><thead><tr><th>Nom</th><th>Email</th><th>Département</th><th>Poste</th><th>Statut</th><th></th></tr></thead><tbody><tr v-for="user in users" :key="user.id"><td>{{ user.nom_complet }}</td><td>{{ user.email }}</td><td>{{ user.departement }}</td><td>{{ user.poste }}</td><td><StatusBadge :status="user.statut" /></td><td class="flex gap-2"><button class="btn btn-success btn-xs" @click="act(user, 'approve')">Approuver</button><button class="btn btn-error btn-xs" @click="act(user, 'reject')">Refuser</button></td></tr><tr v-if="!users.length"><td colspan="6" class="py-10 text-center text-slate-500">Aucun utilisateur en attente.</td></tr></tbody></table></div><div v-if="toast" class="toast toast-end"><div class="alert alert-success">{{ toast }}</div></div></section></AdminLayout></template>
